public ListNode insertNodeAtPosition(ListNode head, int data, int position) {
    if (position == 0) {
        ListNode newNode = new ListNode(data);
        newNode.next = head;
        return newNode;
    }
    head.next = insertNodeAtPosition(head.next, data, position - 1);
    return head;
}

